<link href="https://vjs.zencdn.net/8.22.0/video-js.css" rel="stylesheet" />;

import React, { useEffect, useState } from "react";
import * as Features from "../../Features";
import { SettingsMenu, Contact, Socials } from "..";
import * as Sections from "../Sections";

// video path

const GameEnginePage = (darkMode, toggleDarkMode) => {
  const [isLightboxOpen, setIsLightboxOpen] = useState(false);
  const [lightboxContent, setLightboxContent] = useState("Test");
  const [lightboxStyle, setLightboxStyle] = useState(null);

  const handleOpenLightbox = (content, style) => {
    document.body.classList.add("no-scroll");

    history.pushState({ lightboxOpen: true }, "", "#lightbox");
    setLightboxContent(content);
    setLightboxStyle(style);
    setIsLightboxOpen(true);
  };

  const handleCloseLightbox = () => {
    document.body.classList.remove("no-scroll");
    setIsLightboxOpen(false);
    if (history.state?.lightboxOpen) {
      setTimeout(() => history.back(), 100);
    }
  };
  return (
    <div>
      <Features.LightboxModal
        darkMode={darkMode}
        isOpen={isLightboxOpen}
        content={lightboxContent}
        style={lightboxStyle}
        onClose={handleCloseLightbox}
      />
      <Sections.Header darkMode={darkMode} toggleDarkMode={toggleDarkMode} />
      <main>
        <Features.Section
          title="about"
          darkMode={darkMode}
          revealPercent="50px 0px"
        >
          <div>
            {" "}
            <img
              src={`assets/Images/Peregrine_${
                darkMode ? "dark.png" : "light.png"
              }`}
            ></img>
            <video
              id="my-video"
              class="video-js"
              controls
              preload="auto"
              width="640"
              height="264"
              poster="assets/Videos/Deformable_Volume.jpg"
              data-setup="{}"
            >
              <source
                src="assets/Videos/Deformable_Volume.mp4"
                type="video/mp4"
              />
              <p class="vjs-no-js">
                To view this video please enable JavaScript, and consider
                upgrading to a web browser that
                <a
                  href="https://videojs.com/html5-video-support/"
                  target="_blank"
                >
                  supports HTML5 video
                </a>
              </p>
            </video>
          </div>
        </Features.Section>

        <Features.Section
          title="motivation"
          darkMode={darkMode}
          revealPercent="50px 0px"
        >
          <div className="column-content">
            <div className="game-info">
              <h2>Motivation</h2>
              <p>
                I am passionate about creating interactive experiences that
                engage users and provide them with valuable insights. My goal is
                to use my skills in game development and data visualization to
                create innovative solutions that can help people understand and
                interact with complex data in a more intuitive way.
              </p>
            </div>
          </div>
        </Features.Section>

        <Features.Section
          title="physics"
          darkMode={darkMode}
          revealPercent="50px 0px"
        ></Features.Section>

        <Features.Section
          title="Footer"
          darkMode={darkMode}
          revealPercent="50px 0px"
        >
          <Sections.Footer darkMode={darkMode} />
        </Features.Section>
      </main>
    </div>
  );
};

export default GameEnginePage;
